#include "TDCPlayerCar.h"
#include "Camera/CameraComponent.h"
#include "GameFramework/SpringArmComponent.h"
#include "Components/StaticMeshComponent.h"
#include "Components/InputComponent.h"
#include "UObject/ConstructorHelpers.h"
#include "Engine/StaticMesh.h"
ATDCPlayerCar::ATDCPlayerCar(){PrimaryActorTick.bCanEverTick=true;AutoPossessPlayer=EAutoReceiveInput::Player0;Body=CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Body"));RootComponent=Body;static ConstructorHelpers::FObjectFinder<UStaticMesh>C(TEXT("/Engine/BasicShapes/Cube.Cube"));if(C.Succeeded()){Body->SetStaticMesh(C.Object);Body->SetRelativeScale3D(FVector(4.6,2,.62));Body->SetRelativeLocation(FVector(0,0,70));}Body->SetSimulatePhysics(true);Body->SetLinearDamping(.12f);Body->SetAngularDamping(1.8f);Body->SetMassOverrideInKg(NAME_None,1450,true);Body->SetCollisionProfileName(TEXT("PhysicsActor"));Arm=CreateDefaultSubobject<USpringArmComponent>(TEXT("ChaseArm"));Arm->SetupAttachment(RootComponent);Arm->TargetArmLength=650;Arm->SetRelativeLocation(FVector(-40,0,150));Arm->bEnableCameraLag=true;Arm->CameraLagSpeed=6;Camera=CreateDefaultSubobject<UCameraComponent>(TEXT("Camera"));Camera->SetupAttachment(Arm);Camera->SetFieldOfView(76);}
void ATDCPlayerCar::SetupPlayerInputComponent(UInputComponent* I){Super::SetupPlayerInputComponent(I);I->BindAxis("Throttle",this,&ATDCPlayerCar::SetThrottle);I->BindAxis("Steer",this,&ATDCPlayerCar::SetSteer);I->BindAxis("Brake",this,&ATDCPlayerCar::SetBrake);I->BindAction("Handbrake",IE_Pressed,this,&ATDCPlayerCar::HBDown);I->BindAction("Handbrake",IE_Released,this,&ATDCPlayerCar::HBUp);}
void ATDCPlayerCar::SetThrottle(float V){Throttle=FMath::Clamp(V,-.35f,1.f);}void ATDCPlayerCar::SetSteer(float V){Steer=FMath::Clamp(V,-1.f,1.f);}void ATDCPlayerCar::SetBrake(float V){Brake=V>.1f;}void ATDCPlayerCar::HBDown(){Handbrake=true;}void ATDCPlayerCar::HBUp(){Handbrake=false;}
void ATDCPlayerCar::Tick(float Dt){Super::Tick(Dt);if(!Body||!Body->IsSimulatingPhysics())return;FVector F=Body->GetForwardVector(),V=Body->GetPhysicsLinearVelocity();float S=V.Size();if(Throttle>0&&S<MaxSpeedKmh/3.6f)Body->AddForce(F*1850000.f*Throttle);else if(Throttle<0)Body->AddForce(-F*400000.f);if(Brake)Body->AddForce(-V.GetSafeNormal()*360000.f);if(Handbrake)Body->AddForce(-V.GetSafeNormal()*160000.f);Body->AddTorqueInRadians(FVector(0,0,1450000.f*Steer*FMath::Clamp(S/15.f,.12f,1.f)));FVector R=Body->GetRightVector();Body->AddForce(-R*FVector::DotProduct(V,R)*Body->GetMass()*(Handbrake?1.2f:WetGrip)*5.f);}
